/* course14.js — Course 14 content (Network resilience and scaling; loaded on demand via course-core.js) */
/* ============================================================
   COURSE 14 — Network resilience and scaling (SPOF and high availability, the HA pair
   and failover, load balancing and VIP, the redundancy map STP/HSRP/LAG/multi-WAN,
   designing a resilient network). Practically follows the firewall HA pair, load balancer
   and the resilience audit/test in the simulator.
   Scene c14Net: NET — FW-A / FW-B (HA pair) — LB — WEB-1 / WEB-2.
   ============================================================ */
var C14R={cli:[70,108],fwa:[220,56],fwb:[220,160],lb:[380,108],s1:[530,56],s2:[530,160]};
function c14Net(pfx){
  return '<svg id="'+pfx+'svg" viewBox="0 0 640 216" width="100%" style="display:block">'
    +'<line x1="84" y1="103" x2="206" y2="61" style="stroke:var(--line2);stroke-width:1.6"/>'
    +'<line x1="84" y1="113" x2="206" y2="155" style="stroke:var(--line2);stroke-width:1.6"/>'
    +'<line x1="234" y1="61" x2="366" y2="103" style="stroke:var(--line2);stroke-width:1.6"/>'
    +'<line x1="234" y1="155" x2="366" y2="113" style="stroke:var(--line2);stroke-width:1.6"/>'
    +'<line x1="394" y1="103" x2="516" y2="61" style="stroke:var(--line2);stroke-width:1.6"/>'
    +'<line x1="394" y1="113" x2="516" y2="155" style="stroke:var(--line2);stroke-width:1.6"/>'
    +'<line x1="220" y1="76" x2="220" y2="140" style="stroke:var(--line2);stroke-width:1.4;stroke-dasharray:4 4"/>'
    +'<g id="'+pfx+'glow"></g>'
    +csHost(70,108,'globe','--cyan','NET')
    +csDev(220,56,'firewall','FW-A')+csDev(220,160,'firewall','FW-B')
    +csDev(380,108,'loadbalancer','LB')
    +csHost(530,56,'server','--green','WEB-1')+csHost(530,160,'server','--green','WEB-2')
    +'<g id="'+pfx+'dyn"></g></svg>';
}
function c14P(pfx,intro,terms){
  return '<p style="color:var(--muted);font-size:var(--crs-fs,13.5px);line-height:1.55;margin:0 0 10px">'+intro+'</p>'
    +'<div class="osi-stage">'+c14Net(pfx)+'</div><div class="m1-cap" id="'+pfx+'cap"></div>'
    +courseStepControls(pfx)+abbrBox(terms);
}
function c14Mount(pfx,STEPS){
  function show(i){var g=$(pfx+'glow');if(g)g.innerHTML=STEPS[i].glow||'';var d=$(pfx+'dyn');if(d)d.innerHTML=STEPS[i].dyn||'';var c=$(pfx+'cap');if(c)c.innerHTML='<span>'+STEPS[i].cap+'</span>';}
  courseStepper(pfx,STEPS.length,show);
}
function c14g(name,color){var p=C14R[name];return csGlow(p[0],p[1],color,20);}
function c14lbl(x,y,tx,c){return '<text x="'+x+'" y="'+y+'" text-anchor="middle" style="font:700 7.5px var(--mono);fill:var('+c+')">'+esc(tx)+'</text>';}
function c14pkt(path,color,dur){return '<rect x="-6" y="-4" width="12" height="9" rx="2" style="fill:var('+color+')"><animateMotion path="'+path+'" dur="'+(dur||'1.4s')+'" repeatCount="indefinite"/></rect>';}

/* ---------- L1M1 — A single point of failure ---------- */
function renderC14Spof(){return c14P('raa',
  'In earlier courses you built networks that <b>work</b>. Now we teach them to <b>survive when something breaks</b> – because eventually it always does. Power fails, someone trips over a cable, a device dies after years of service. The key term is <b>SPOF</b> (single point of failure): a device whose failure takes down the <b>whole</b> network because no backup path exists. Look at the scene as a packet’s journey from internet users (NET) to a web server: NET → firewall → load balancer → server. If each device in that row existed only once, it would be a <b>chain of pure SPOFs</b> – one link snaps and the whole service is down. That is why the scene shows devices <b>doubled</b>: two firewalls (FW-A, FW-B), two web servers (WEB-1, WEB-2) and a load balancer between them. That is not waste – it is insurance. The rest of the course is about a single question: <b>where in the network is a SPOF and how to remove it</b>, without turning a simple network into an unmanageable monster.',
  [['SPOF','a single point of failure – a device whose failure takes down the whole network because there is no backup path.'],['redundancy','deploying a device or path twice so the failure of one piece does not bring the service down.']]);}
function mountC14Spof(){c14Mount('raa',[
  {glow:c14g('cli','--green')+c14g('fwa','--green')+c14g('lb','--green')+c14g('s1','--green'),dyn:c14pkt('M 70 108 L 220 56 L 380 108 L 530 56','--green')+c14lbl(150,211,'normal traffic: NET → FW → LB → server','--green'),cap:'Traffic flows from internet users through the firewall and load balancer to the web server. So far so good.'},
  {glow:c14g('fwa','--red'),dyn:c14lbl(220,211,'the only firewall fails = SPOF ⚠','--red'),cap:'If the firewall existed <b>only once</b>, its failure would cut off everything. That is a <b>SPOF</b>: a single point of failure.'},
  {glow:c14g('cli','--blue')+c14g('fwb','--blue')+c14g('lb','--blue')+c14g('s2','--blue'),dyn:c14pkt('M 70 108 L 220 160 L 380 108 L 530 160','--blue')+c14lbl(150,211,'redundancy: a backup path exists','--blue'),cap:'So devices are <b>doubled</b>: if FW-A fails, traffic goes via FW-B; if WEB-1 fails, WEB-2 serves. The SPOF is gone.'},
  {glow:c14g('lb','--amber'),dyn:c14lbl(380,211,'watch out: what about the load balancer itself?','--amber'),cap:'But doubling one device can reveal the next SPOF: what if the load balancer is <b>the only one</b>? Hunting SPOFs is a whole-course job.'}
]);}
/* ---------- L1M2 — High availability and N-1 ---------- */
function renderC14HaConcept(){return c14P('rab',
  'When you remove a SPOF, you gain <b>high availability</b> (HA): the ability of the network to keep running even when something breaks. Engineers have a short rule for it – <b>N-1</b>: the network must withstand the failure of <b>any one</b> device and still serve traffic. Two firewalls? One may fail (N-1) and the other carries it. Three servers where two can handle the load? Also N-1. The point is not to have two of everything ‘for comfort’, but to deliberately compute how many devices may fail at once without the service dropping. How good is availability ‘enough’? It is measured as the percentage of time the service runs. The often-quoted target of <b>‘five nines’</b> (99.999%) means only a few minutes of outage over a <b>whole year</b> – and it is enormously expensive. Two numbers that will haunt you: <b>MTBF</b> (mean time between failures – how long a device lasts on average without a fault) and <b>RTO</b> (recovery time objective – how quickly you must recover once a fault does occur). Remember the meaning, not the formulas: <b>N-1 says how much may fail at once; RTO says how fast the network recovers from it.</b>',
  [['N-1','the network withstands the failure of any single device and still serves traffic.'],['high availability (HA)','the ability to keep running through a fault; measured as the percentage of time the service is up.'],['RTO','recovery time objective – how fast the network must recover once a fault happens.']]);}
function mountC14HaConcept(){c14Mount('rab',[
  {glow:c14g('cli','--green')+c14g('fwa','--green')+c14g('lb','--green')+c14g('s1','--green'),dyn:c14pkt('M 70 108 L 220 56 L 380 108 L 530 56','--green')+c14lbl(150,211,'N devices: all running','--green'),cap:'High availability = the network keeps running through a fault. The <b>N-1</b> rule: it must withstand the loss of any single device.'},
  {glow:c14g('fwa','--red')+c14g('cli','--blue')+c14g('fwb','--blue')+c14g('lb','--blue')+c14g('s1','--blue'),dyn:c14pkt('M 70 108 L 220 160 L 380 108 L 530 56','--blue')+c14lbl(150,211,'N-1: FW-A drops, FW-B carries it','--blue'),cap:'FW-A failed – the second firewall takes over and the service keeps running. That is N-1 in practice.'},
  {glow:c14g('s1','--amber'),dyn:c14lbl(530,108,'MTBF: how long a device lasts','--amber'),cap:'<b>MTBF</b> says how long a device lasts on average without a fault – but no number ever means ‘never fails’.'},
  {glow:c14g('cli','--cyan')+c14g('fwb','--cyan')+c14g('lb','--cyan')+c14g('s2','--cyan'),dyn:c14lbl(150,211,'RTO: how fast the network recovers','--cyan'),cap:'And <b>RTO</b> says how fast the network recovers after a fault. ‘Five nines’ (99.999%) = a few minutes of outage a year – and it is expensive.'}
]);}
/* ---------- L1M3 — Find the SPOF: audit and resilience test ---------- */
function renderC14Audit(){return c14P('rac',
  'You will now <b>get hands-on with SPOF and N-1 right in the simulator</b> – and two tools help nicely. The first is the <b>topology check</b>: it walks your network and flags weak spots, including devices and links that are the <b>only one of their kind</b> on a critical path. The second is the <b>resilience test</b> (an N-1 check): the simulator ‘switches off’ each device in turn and checks whether traffic from source to destination still gets through. A device whose removal makes the connection <b>drop</b> is your SPOF – exactly the one the audit pointed at. Try it: build a simple row (client → one firewall → server), run the resilience test, and you will see that switching off the firewall breaks the connection. Then add a second firewall as an <b>HA pair</b> (lesson 2 shows exactly how), run the test again – and the service now survives one firewall failing. This cycle of <b>‘find the SPOF → double it → verify by test’</b> is the heart of resilient network design. Learn one discipline along the way: do not scale blindly. First find <b>where</b> it hurts most (audit), only then add – and after every change <b>verify</b> that the SPOF is really gone and no new one appeared.',
  [['topology check','a simulator tool that walks the network and flags weak spots and SPOFs on the critical path.'],['resilience test (N-1)','switches off each device in turn and checks whether traffic still reaches the destination.']])
  +courseCTA('racTask','Try it for real – the core switch just failed and you build the backup path: the task "A single point of failure: build a backup path".','Open the task');}
function mountC14Audit(){c14Mount('rac',[
  {glow:c14g('cli','--amber')+c14g('fwa','--amber')+c14g('lb','--amber')+c14g('s1','--amber'),dyn:c14pkt('M 70 108 L 220 56 L 380 108 L 530 56','--amber')+c14lbl(150,211,'a simple row: client → FW → server','--amber'),cap:'Build a simple row in the simulator and run a <b>topology check</b> over it – it lists the critical weak spots.'},
  {glow:c14g('fwa','--red'),dyn:c14lbl(220,211,'resilience test drops FW → connection fails ⚠','--red'),cap:'The <b>resilience test</b> switches off the firewall and retries – it drops. This device is a SPOF.'},
  {glow:c14g('cli','--green')+c14g('fwa','--green')+c14g('fwb','--green')+c14g('s1','--green'),dyn:c14lbl(220,211,'add a second FW as an HA pair','--green'),cap:'Add a second firewall as an <b>HA pair</b> (lesson 2). Now a backup path via FW-B exists.'},
  {glow:c14g('cli','--cyan')+c14g('fwb','--cyan')+c14g('lb','--cyan')+c14g('s1','--cyan'),dyn:c14pkt('M 70 108 L 220 160 L 380 108 L 530 56','--cyan')+c14lbl(150,211,'test again: it survives the failure ✓','--cyan'),cap:'The design cycle: <b>find the SPOF → double it → verify by test</b>. And after each change check no new one appeared.'}
]);
  var b=$('racTask');if(b)b.onclick=function(){courseTry('spof-fix');};
}
/* ---------- L2M1 — Active/standby vs active/active ---------- */
function renderC14HaModes(){return c14P('rad',
  'The most common way to remove a SPOF at a firewall or router is an <b>HA pair</b>: two identical devices that agree to act as one logical unit, each ready to stand in for the other. There are two modes. <b>Active/standby</b>: one device (FW-A) handles all traffic, the other (FW-B) waits quietly as a backup and continuously checks the active one is alive. When the active drops, the standby <b>wakes and takes over</b> its role. Upside: simple, predictable, no arguments about who does what. Downside: the standby <b>does nothing most of the time</b> – you pay for two units and use one. <b>Active/active</b>: <b>both</b> devices handle traffic at once and share the load; when one drops, the other picks up its share too. Upside: you use both units and get more capacity. Downside: more complex – you must keep both seeing the same connection state, and after a failure the survivor must carry the <b>full</b> load (so even an active/active pair must not be loaded to 100%, or the survivor is overloaded after a failure). In the simulator, a firewall or L3 device has an <b>HA</b> section with the mode choice: active/active, or active/standby. Exactly how that ‘takeover’ happens is the next module.',
  [['active/standby','one serves, the other waits as backup and takes over the role when the active fails.'],['active/active','both serve and share the load; when one fails the other picks up its share too.']]);}
function mountC14HaModes(){c14Mount('rad',[
  {glow:c14g('cli','--green')+c14g('fwa','--green')+c14g('lb','--green'),dyn:c14pkt('M 70 108 L 220 56 L 380 108','--green')+c14lbl(150,211,'active/standby: FW-A serves','--green'),cap:'<b>Active/standby</b>: FW-A serves all traffic. FW-B waits quietly as a backup.'},
  {glow:c14g('fwb','--muted'),dyn:c14lbl(220,211,'the backup does nothing most of the time','--muted'),cap:'The price of simplicity: standby FW-B <b>mostly just waits</b> – you pay for two units and use one.'},
  {glow:c14g('cli','--blue')+c14g('fwa','--blue')+c14g('fwb','--blue')+c14g('lb','--blue'),dyn:c14pkt('M 70 108 L 220 160 L 380 108','--blue','1.1s')+c14lbl(150,211,'active/active: both serve and share load','--blue'),cap:'<b>Active/active</b>: both devices serve at once and share the load. You use both units and get more capacity.'},
  {glow:c14g('fwa','--amber')+c14g('fwb','--amber'),dyn:c14lbl(220,211,'don’t load to 100% – survive a failure','--amber'),cap:'Caution: even an active/active pair must not run at 100%. After a failure the survivor carries the <b>full</b> load. In the simulator: the HA section + mode.'}
]);}
/* ---------- L2M2 — How failover happens ---------- */
function renderC14Failover(){return c14P('rae',
  'How exactly does the ‘takeover’ happen? It is called <b>failover</b> and has three phases. <b>1) Detection.</b> The devices in an HA pair send each other short ‘I’m alive’ messages (a heartbeat) over a dedicated link. As long as FW-B hears FW-A’s pulse, it does nothing. When the pulse <b>goes silent</b> for a moment, FW-B concludes the active one has failed. <b>2) Takeover.</b> The standby declares itself the new active and <b>assumes the identity</b> the rest of the network sends traffic to – chiefly the shared <b>virtual IP and MAC address</b> of the gateway (you know this trick from the course <i>The router in depth</i> as HSRP/VRRP: clients talk to one unchanging gateway address even as the physical device beneath it swaps). <b>3) Redirection.</b> Neighboring devices learn the address now belongs to a different device and traffic starts flowing through it. The key number is how long all this takes – the <b>failover time</b>. A well-tuned pair does it in <b>seconds or fractions of a second</b>: the user notices at most a brief stutter, an existing download may need to resume, but the service as a whole keeps going. You will try it directly in the simulator: build an HA firewall pair and in the active one’s context menu choose <b>‘Simulate failure (HA)’</b>. You will watch the standby take over and traffic find the new path – exactly what you verified with the resilience test in lesson 1.',
  [['failover','the standby automatically taking over the active role after a failure – detection, identity takeover, redirection.'],['heartbeat','short ‘I’m alive’ messages between HA-pair members; their silence triggers failover.'],['virtual IP','a shared gateway address the new active device assumes – clients keep the same address (HSRP/VRRP, the course <i>The router in depth</i>).']]);}
function mountC14Failover(){c14Mount('rae',[
  {glow:c14g('fwa','--green')+c14g('fwb','--green'),dyn:c14lbl(268,118,'heartbeat link','--green'),cap:'<b>Detection</b>: the firewalls send ‘I’m alive’ (a heartbeat) over a dedicated link. While FW-B hears the pulse, it does nothing.'},
  {glow:c14g('fwa','--red'),dyn:c14lbl(220,211,'the pulse went silent → FW-A failed','--red'),cap:'FW-A fails, the pulse <b>goes silent</b>. After a moment FW-B concludes the active device is gone.'},
  {glow:c14g('fwb','--blue'),dyn:c14lbl(220,211,'FW-B assumes the gateway’s virtual IP','--blue'),cap:'<b>Takeover</b>: FW-B declares itself active and assumes the gateway’s <b>virtual IP/MAC</b> – clients keep the same address (like HSRP/VRRP).'},
  {glow:c14g('cli','--cyan')+c14g('fwb','--cyan')+c14g('lb','--cyan')+c14g('s2','--cyan'),dyn:c14pkt('M 70 108 L 220 160 L 380 108 L 530 160','--cyan')+c14lbl(150,211,'traffic flows via FW-B (seconds) ✓','--cyan'),cap:'<b>Redirection</b>: traffic flows via FW-B, the whole thing takes seconds. In the simulator: choose ‘Simulate failure (HA)’ in the active one’s menu.'}
]);}
/* ---------- L2M3 — State synchronization and split-brain ---------- */
function renderC14Sync(){return c14P('raf',
  'The failover from the previous module has a catch worth thinking through. A firewall is <b>stateful</b> (recall the course <i>Network security</i>): it remembers a table of open connections so it can let replies back through. When the active FW-A fails and FW-B takes over, what happens to the <b>thousands of connections in progress</b>? If FW-B knows nothing about them, it treats them as ‘unsolicited’ and <b>drops</b> them – users lose calls, transfers, logins, even though the network itself is ‘up’. The fix is <b>state synchronization</b>: the active device continuously <b>copies its connection table</b> to the backup, so at the moment of takeover FW-B knows every connection and continues them seamlessly. Failover then becomes almost invisible to users. The second catch is called <b>split-brain</b>: what if the active firewall did not fail, but only the <b>link between them</b> carrying the heartbeat did? FW-A lives on and keeps serving – but FW-B hears no pulse, concludes FW-A died, and also declares itself active. Suddenly there are <b>two actives</b>, both claiming the same virtual IP, and the network descends into chaos. The fix is beyond a beginner course (a second independent heartbeat link, a ‘vote’ on who may be active) – it is enough for you to <b>know split-brain exists</b> and to understand why HA must never rest on a single interconnect link.',
  [['state synchronization','the active copies its connection table to the backup so failover does not drop live connections.'],['split-brain','a heartbeat-link failure makes both devices declare themselves active at once – network chaos.']])
  +courseCTA('rafTask','See an HA pair live and simulate the active firewall failing: the task "Firewall HA pair: failover".','Open the task');}
function mountC14Sync(){c14Mount('raf',[
  {glow:c14g('fwa','--green')+c14g('fwb','--green'),dyn:c14lbl(276,118,'connection-table sync','--green'),cap:'A firewall is <b>stateful</b>: it remembers open connections. The active copies them to the backup continuously – <b>state synchronization</b>.'},
  {glow:c14g('cli','--cyan')+c14g('fwb','--cyan')+c14g('lb','--cyan')+c14g('s1','--cyan'),dyn:c14pkt('M 70 108 L 220 160 L 380 108 L 530 56','--cyan')+c14lbl(150,211,'failover keeps live connections ✓','--cyan'),cap:'Thanks to sync, FW-B knows every connection and continues them seamlessly – failover is almost invisible to users.'},
  {glow:c14g('fwa','--amber')+c14g('fwb','--amber'),dyn:c14lbl(220,211,'only the link between them fails ⚠','--amber'),cap:'The catch: what if only the <b>heartbeat link</b> fails, not the firewall? FW-A lives, but FW-B cannot hear it.'},
  {glow:c14g('fwa','--red')+c14g('fwb','--red'),dyn:c14lbl(220,211,'split-brain: two actives at once','--red'),cap:'<b>Split-brain</b>: both declare themselves active and claim the same virtual IP. So never build HA on a single link.'}
]);
  var b=$('rafTask');if(b)b.onclick=function(){courseTry('ha-failover');};
}
/* ---------- L3M1 — Scale-up vs scale-out and the VIP ---------- */
function renderC14ScaleOut(){return c14P('rag',
  'An HA pair solves <b>availability</b> – keeping the service alive through a failure. But what if the service cannot keep up because it <b>gained users</b>? You have two paths. <b>Scale-up</b>: take the existing server and give it more power – a faster CPU, more memory. Simple, but it hits a ceiling: the strongest machine has finite capacity, is expensive, and is again <b>one big SPOF</b>. <b>Scale-out</b>: instead of one big server, deploy <b>several smaller ones</b> and split the load among them. This approach has two magics at once: it handles almost any growth (add another server) and it is <b>inherently resilient</b> – if one server dies, the others keep running. That is exactly why the scene shows two web servers. But how do clients know which one to connect to? They must not have to – that is the job of the <b>load balancer</b>. Clients talk to a <b>single</b> address called a <b>VIP</b> (virtual IP of the service). The load balancer sits behind that VIP, <b>assigns each incoming connection to one of the servers in the pool</b>, and sends the reply back. The user has no idea how many servers stand behind the VIP, whether it is five or fifty – they see <b>one service</b>. Exactly how the LB picks a server, and how it knows one is dead, is in the next two modules.',
  [['scale-up vs scale-out','up = one stronger machine (has a ceiling, is a SPOF); out = more smaller machines sharing load (grows and survives a failure).'],['VIP','the service’s virtual IP: the single address clients talk to; behind it sits the load balancer and the server pool.'],['load balancer','a load balancer – assigns each connection to a server in the pool and hides them behind one VIP.']]);}
function mountC14ScaleOut(){c14Mount('rag',[
  {glow:c14g('s1','--amber'),dyn:c14lbl(530,108,'scale-up: one server, more power (a ceiling) ⚠','--amber'),cap:'<b>Scale-up</b>: give one server more power. Simple, but it has a ceiling – and is again one big SPOF.'},
  {glow:c14g('lb','--green')+c14g('s1','--green')+c14g('s2','--green'),dyn:c14lbl(455,211,'scale-out: more servers, shared load','--green'),cap:'<b>Scale-out</b>: deploy more smaller servers and split the load. It grows almost freely and is inherently resilient.'},
  {glow:c14g('cli','--blue')+c14g('fwa','--blue')+c14g('lb','--blue'),dyn:c14pkt('M 70 108 L 220 56 L 380 108','--blue')+c14lbl(150,211,'client talks to one address (VIP)','--blue'),cap:'The client talks to a <b>single</b> address – the <b>VIP</b>. It has no idea how many servers stand behind it; it sees one service.'},
  {glow:c14g('lb','--cyan')+c14g('s1','--cyan')+c14g('s2','--cyan'),dyn:c14pkt('M 380 108 L 530 56','--cyan')+c14lbl(455,211,'the LB assigns the connection to a pool server','--cyan'),cap:'Behind the VIP sits the <b>load balancer</b>: it assigns each connection to a server in the pool and sends the reply back.'}
]);}
/* ---------- L3M2 — Balancing algorithms ---------- */
function renderC14Algos(){return c14P('rah',
  'By what does a load balancer choose which server a new connection goes to? It has several <b>algorithms</b>, and they are worth understanding because each fits a different case. <b>Round-robin</b>: it hands out connections in turn – the first to WEB-1, the second to WEB-2, the third to WEB-1 again… Fair and simple, ideal when the servers are <b>equally strong</b> and requests are roughly equally heavy. <b>Least-connections</b>: it sends a new connection where there are <b>currently the fewest</b> open connections. Better when requests <b>vary in length</b> – a server stuck on a few heavy transfers gets no more until it frees up. <b>Weighted</b>: you assign servers <b>weights</b> by power; a stronger machine gets more connections than a weaker one. Handy when your servers are <b>unequal</b>. <b>Source-IP</b> (by the client’s address): the same client always goes to the <b>same server</b>. Why would anyone want that? Because of <b>sticky sessions</b>: some applications keep login state or cart contents <b>locally on the server</b> where you started. If the LB sent you elsewhere next time, you would lose the cart. Source-IP (or a cookie) therefore <b>sticks</b> you to ‘your’ server. A side note: stickiness is a crutch – it is cleaner when servers keep the state in <b>shared storage outside themselves</b> (a common database or cache), so it does not matter which one you land on. In the simulator, a load balancer offers exactly these algorithms: rr, leastconn, weighted, srcip.',
  [['round-robin','hands connections out in turn among servers; ideal when they are equally strong.'],['least-connections','sends a connection where there are currently the fewest open ones; better for varied-length requests.'],['weighted','a stronger server gets more connections by its assigned weight; for unequal machines.'],['sticky session (source-IP)','the same client keeps going to the same server because the app holds state there (login, cart).']]);}
function mountC14Algos(){c14Mount('rah',[
  {glow:c14g('lb','--green')+c14g('s1','--green')+c14g('s2','--green'),dyn:'<rect x="-6" y="-4" width="12" height="9" rx="2" style="fill:var(--green)"><animateMotion path="M 380 108 L 530 56" dur="2s" begin="0s" repeatCount="indefinite"/></rect><rect x="-6" y="-4" width="12" height="9" rx="2" style="fill:var(--green)"><animateMotion path="M 380 108 L 530 160" dur="2s" begin="1s" repeatCount="indefinite"/></rect>'+c14lbl(455,211,'round-robin: alternates WEB-1 and WEB-2','--green'),cap:'<b>Round-robin</b>: hands connections out in turn – WEB-1, WEB-2, WEB-1… Ideal when servers are equally strong.'},
  {glow:c14g('lb','--blue')+c14g('s2','--blue'),dyn:c14pkt('M 380 108 L 530 160','--blue')+c14lbl(455,211,'least-conn: where the fewest connections are now','--blue'),cap:'<b>Least-connections</b>: a new connection goes where the fewest are open now. Better for varied-length requests.'},
  {glow:c14g('lb','--violet')+c14g('s1','--violet'),dyn:c14pkt('M 380 108 L 530 56','--violet','0.8s')+c14lbl(455,211,'weighted: the stronger server gets more','--violet'),cap:'<b>Weighted</b>: assign weights by power – the stronger machine gets more connections. For unequal servers.'},
  {glow:c14g('cli','--amber')+c14g('fwa','--amber')+c14g('lb','--amber')+c14g('s2','--amber'),dyn:c14pkt('M 70 108 L 220 56 L 380 108 L 530 160','--amber')+c14lbl(150,211,'source-IP: same client → same server','--amber'),cap:'<b>Source-IP</b>: the same client keeps hitting the same server – a <b>sticky session</b>, because the app holds state there (cart, login).'}
]);}
/* ---------- L3M3 — Health check ---------- */
function renderC14Health(){return c14P('rai',
  'A load balancer that splits load blindly has a hidden trap: what if one server in the pool <b>fails</b>? If the LB did not know, it would keep dutifully sending every Nth connection to it – and each such user would hit a <b>dead server</b> and get an error. Load balancing would thus paradoxically <b>worsen</b> availability. That is why every serious load balancer runs a <b>health check</b>: it regularly <b>asks each server in the pool whether it is alive</b> – from a plain ‘do you answer on the network?’ to a smarter ‘return me a test page and I will check the answer makes sense’. A server that stops answering is <b>removed from the pool</b> by the LB, which stops sending it traffic. Users never notice – connections flow smoothly to the remaining healthy servers. And once the server recovers and starts answering again, the LB <b>puts it back</b>. Notice how both halves of the course meet here: the load balancer not only scales out (more capacity), but thanks to the health check it <b>also provides resilience</b> – it removes the ‘dead backend’ SPOF by itself. In the simulator, build a VIP on the load balancer with a pool of two servers, send traffic through the VIP and watch it split. Then ‘switch off’ one backend and confirm traffic keeps flowing only to the healthy one. That is scale-out and resilience in one picture.',
  [['health check','the LB regularly asks pool servers if they are alive; it removes dead ones and returns recovered ones.'],['removing a backend','a server failing the health check is dropped by the LB – users never notice.']])
  +courseCTA('raiTask','Watch a load balancer at work – the VIP, balancing and a dead backend: the task "Load balancer: spreading the load".','Open the task');}
function mountC14Health(){c14Mount('rai',[
  {glow:c14g('lb','--green')+c14g('s1','--green')+c14g('s2','--green'),dyn:c14lbl(455,211,'the LB asks: ‘alive?’ (health check)','--green'),cap:'The load balancer regularly asks each server in the pool <b>whether it is alive</b> – that is the <b>health check</b>.'},
  {glow:c14g('s1','--red'),dyn:c14lbl(530,108,'WEB-1 does not answer → dead ⚠','--red'),cap:'WEB-1 fails and stops answering. A blind LB would keep sending it every Nth connection – all errors.'},
  {glow:c14g('cli','--cyan')+c14g('fwa','--cyan')+c14g('lb','--cyan')+c14g('s2','--cyan'),dyn:c14pkt('M 70 108 L 220 56 L 380 108 L 530 160','--cyan')+c14lbl(150,211,'LB drops WEB-1, flows only to WEB-2 ✓','--cyan'),cap:'The health check <b>removes WEB-1 from the pool</b>; traffic flows smoothly only to the healthy WEB-2. Users notice nothing.'},
  {glow:c14g('lb','--blue')+c14g('s1','--blue')+c14g('s2','--blue'),dyn:c14lbl(455,211,'WEB-1 recovers → the LB returns it','--blue'),cap:'Once WEB-1 answers again, the LB <b>returns it to the pool</b>. So the LB scales out <b>and</b> removes the ‘dead backend’ SPOF.'}
]);
  var b=$('raiTask');if(b)b.onclick=function(){courseTry('lb-web');};
}
/* ---------- L4M1 — L2 and gateway redundancy ---------- */
function renderC14MapL2(){return c14P('raj',
  'You have two big resilience techniques behind you – the HA pair and load balancing. Now it is time to <b>assemble the map</b>: a network has several places where a SPOF lurks, and each calls for a <b>different</b> tool. You have met most of them in earlier courses; here we gather them in one place. Start <b>from the bottom</b>. <b>The L2 layer – loops:</b> when you run a backup cable between switches you gain redundancy, but also a dangerous <b>loop</b> in which frames circle forever (a broadcast storm). The fix is <b>STP</b> (Spanning Tree Protocol, the course <i>Redundancy and Spanning Tree</i>): it keeps the backup link <b>blocked</b>, and when the main one fails it safely opens the loop. Redundancy without the storm. <b>The gateway layer (default gateway):</b> computers have one gateway out configured – and if that router failed, the whole subnet would go mute even if another path existed. The fix is <b>HSRP/VRRP</b> (the course <i>The router in depth</i>): two routers share <b>one virtual gateway IP</b>; clients keep it unchanged, and when the active router leaves, the other assumes it – exactly the same trick as the firewall HA pair from lesson 2, just at the gateway level. You see the pattern running through the whole course: <b>one shared identity, two devices, a quiet takeover.</b> The next module adds redundancy of capacity and of the internet connection.',
  [['STP','keeps a backup L2 link blocked against a loop and opens it when the main one fails (the course <i>Redundancy and Spanning Tree</i>).'],['HSRP/VRRP','two routers share a virtual gateway IP; when the active fails the other assumes it (the course <i>The router in depth</i>).']]);}
function mountC14MapL2(){c14Mount('raj',[
  {glow:c14g('fwa','--amber')+c14g('fwb','--amber'),dyn:c14lbl(220,211,'a backup L2 link = a loop ⚠','--amber'),cap:'From the bottom: a backup cable between switches gives redundancy but also a dangerous <b>loop</b> (a broadcast storm).'},
  {glow:c14g('fwa','--green')+c14g('lb','--green')+c14g('fwb','--red'),dyn:c14pkt('M 220 56 L 380 108','--green')+'<line x1="234" y1="155" x2="366" y2="113" style="stroke:var(--red);stroke-width:2.4;stroke-dasharray:5 4"/><line x1="290" y1="122" x2="310" y2="146" style="stroke:var(--red);stroke-width:2.4"/>'+c14lbl(300,190,'BLOCK','--red')+c14lbl(300,211,'STP: keeps the backup blocked (the course <i>Redundancy and Spanning Tree</i>)','--green'),cap:'<b>STP</b> keeps the backup link blocked and opens it only when the main fails – redundancy without the storm (the course <i>Redundancy and Spanning Tree</i>).'},
  {glow:c14g('cli','--red')+c14g('fwa','--red'),dyn:c14lbl(150,211,'the only gateway fails = the subnet goes mute ⚠','--red'),cap:'The gateway layer: if the only default router failed, the whole subnet goes mute even if another path exists.'},
  {glow:c14g('cli','--cyan')+c14g('fwb','--cyan'),dyn:c14pkt('M 70 108 L 220 160','--cyan')+c14lbl(150,211,'HSRP/VRRP: a shared virtual gateway (the course <i>The router in depth</i>)','--cyan'),cap:'<b>HSRP/VRRP</b>: two routers share one virtual gateway IP; the other assumes it on failure – the same trick as the HA pair (the course <i>The router in depth</i>).'}
]);}
/* ---------- L4M2 — Capacity and WAN redundancy ---------- */
function renderC14MapWan(){return c14P('rak',
  'We continue the redundancy map two floors higher. <b>Link capacity:</b> what if one link between switches cannot carry the traffic – or you want a single cable failing to limit no one? You can bundle <b>several physical links into one logical link</b>. This is called <b>EtherChannel</b> (or generally <b>LAG</b> – link aggregation, the course <i>Redundancy and Spanning Tree</i>): four cables act as one thick one, their speed adds up <b>and</b> it survives any one of them failing – the rest keep going, just at lower capacity. Two birds with one stone: more throughput and resilience. <b>The internet connection (WAN):</b> the most precious SPOF of all – if your single link to the provider drops, no internal redundancy helps, you cannot get out. The fix is <b>multi-WAN</b>: have <b>two connections from two providers</b> (ideally on different technologies too – fiber and mobile). In normal times you can even split traffic across both; when one fails, <b>failover</b> redirects everything to the other (here the floating static route from the courses <i>Routing and IP addresses</i> and <i>The router in depth</i> returns – a backup route with a worse metric that activates once the main one disappears). Remember the logic: <b>EtherChannel handles capacity and internal failure, multi-WAN handles failure of the path out.</b> The next module condenses the whole map into a single ‘where to use what’ table.',
  [['EtherChannel / LAG','bundles several physical links into one logical link – adds capacity and survives any one of them failing (the course <i>Redundancy and Spanning Tree</i>).'],['multi-WAN','two internet connections from two providers; on one failing, failover redirects to the other.']]);}
function mountC14MapWan(){c14Mount('rak',[
  {glow:c14g('fwa','--green')+c14g('lb','--green'),dyn:c14pkt('M 220 56 L 380 108','--green','0.7s')+c14lbl(300,211,'EtherChannel: several cables as one','--green'),cap:'<b>EtherChannel/LAG</b>: bundles several physical links into one – adds speed and survives any one failing (the course <i>Redundancy and Spanning Tree</i>).'},
  {glow:c14g('cli','--red'),dyn:c14lbl(90,211,'a single WAN link = the most precious SPOF ⚠','--red'),cap:'The most precious SPOF: the single link to the provider. It drops – and no internal redundancy gets you out.'},
  {glow:c14g('cli','--blue')+c14g('fwa','--blue'),dyn:c14pkt('M 70 108 L 220 56','--blue')+c14lbl(150,211,'multi-WAN: two providers','--blue'),cap:'<b>Multi-WAN</b>: two connections from two providers, ideally on different technologies (fiber + mobile).'},
  {glow:c14g('cli','--cyan')+c14g('fwb','--cyan'),dyn:c14pkt('M 70 108 L 220 160','--cyan')+c14lbl(150,211,'failover to the other link (floating static)','--cyan'),cap:'When one WAN drops, <b>failover</b> redirects everything to the other – the floating static route from the courses <i>Routing and IP addresses</i> and <i>The router in depth</i> returns.'}
]);}
/* ---------- L4M3 — The whole redundancy map ---------- */
function renderC14MapAll(){return c14P('ral',
  'Let us gather the redundancy map in one place – this is the module you will come back to. Each network layer has <b>its own</b> tool, and the key is to use the right one, not to force the same thing everywhere. <b>L2 (links between switches):</b> <b>STP/RSTP</b> against loops (keeps the backup blocked), <b>EtherChannel/LAG</b> for capacity and resilience (bundles links). <b>Gateway (first hop out):</b> <b>HSRP/VRRP</b> – two routers, one virtual IP. <b>Firewall and L3 devices:</b> an <b>HA pair</b> (active/standby or active/active) with state synchronization. <b>Servers and applications:</b> a <b>load balancer</b> with a VIP, pool and health check – it scales out and removes a dead backend by itself. <b>Path to the internet:</b> <b>multi-WAN</b> with two providers and failover. Notice two patterns recur across all of it. First: <b>shared identity + quiet takeover</b> (the virtual IP in HSRP, the HA pair and multi-WAN failover). Second: <b>split the load across several units</b> (the load balancer, EtherChannel, active/active). Resilience is thus not one magic box – it is the <b>discipline of hunting SPOFs layer by layer</b> and applying each layer’s proven tool. And beware the last, most often forgotten layer that no protocol solves: <b>power and physics</b>. Two power supplies, two feeds, a backup battery (UPS), servers in two different rooms or buildings. The cleverest HA pair is useless when both units hang on one socket.',
  [['layer → tool','L2: STP and LAG; gateway: HSRP/VRRP; firewall: HA pair; servers: load balancer; internet: multi-WAN.'],['power and physics','the most forgotten layer: two power supplies, a UPS, two rooms – no protocol solves it.']]);}
function mountC14MapAll(){c14Mount('ral',[
  {glow:c14g('cli','--green')+c14g('fwa','--green')+c14g('lb','--green')+c14g('s1','--green'),dyn:c14lbl(150,211,'each layer has its own tool','--green'),cap:'The redundancy map: L2 → STP/LAG, gateway → HSRP/VRRP, firewall → HA pair, servers → load balancer, internet → multi-WAN.'},
  {glow:c14g('cli','--cyan')+c14g('fwb','--cyan')+c14g('lb','--cyan'),dyn:c14pkt('M 70 108 L 220 160 L 380 108','--cyan')+c14lbl(150,211,'pattern 1: shared identity + quiet takeover','--cyan'),cap:'Pattern 1: <b>shared identity + quiet takeover</b> – the virtual IP in HSRP, the HA pair and multi-WAN failover.'},
  {glow:c14g('lb','--blue')+c14g('s1','--blue')+c14g('s2','--blue'),dyn:c14pkt('M 380 108 L 530 160','--blue')+c14lbl(455,211,'pattern 2: split load across units','--blue'),cap:'Pattern 2: <b>split the load across units</b> – the load balancer, EtherChannel, active/active pair.'},
  {glow:c14g('s1','--red')+c14g('s2','--red'),dyn:c14lbl(455,211,'don’t forget: power and physics ⚠','--red'),cap:'The most forgotten layer: <b>power and physics</b> – two supplies, a UPS, two rooms. An HA pair on one socket is useless.'}
]);}
/* ---------- L5M1 — Layer the redundancy ---------- */
function renderC14Layers(){return c14P('ram',
  'The last lesson is about design: how to assemble the individual tools into a network that truly holds. The first and most important rule: <b>no single redundancy is enough on its own</b>. You can have the finest HA firewall pair – but if a <b>single</b> server hangs behind it, the service drops anyway. You can have ten servers behind a load balancer – but if the <b>load balancer itself is just one</b>, you have just made it the new SPOF. Resilience is therefore designed <b>in layers</b>, and a chain is only as strong as its <b>weakest link</b>. Walk the packet’s path end to end and at <b>every</b> hop ask ‘and what if this piece dies?’: the internet (→ multi-WAN), the gateway (→ HSRP), the firewall (→ HA pair), the balancer and the servers (→ a load balancer with a pool, and even two LBs in HA – sharing a virtual IP with the same trick as HSRP or the firewall HA pair from lesson 4), and beneath it all the switches and links (→ STP, LAG) and the power (→ two supplies, a UPS). Only when <b>every</b> link of the chain has a backup do you truly have a resilient network – and that is exactly what the <b>resilience test</b> from lesson 1 tells you after each change: it runs N-1 across the whole topology and shows whether a lonely device remains somewhere whose failure takes everything down. Resilience design is thus not a one-off act but a <b>loop</b>: build a layer, test N-1, find the weakest link, strengthen it, test again.',
  [['no single redundancy suffices','a chain is only as strong as its weakest link – every hop on the packet’s path needs a backup.'],['the design loop','build a layer → test N-1 → find the weakest link → strengthen → test again.']]);}
function mountC14Layers(){c14Mount('ram',[
  {glow:c14g('cli','--green')+c14g('fwa','--green')+c14g('fwb','--green'),dyn:c14lbl(220,211,'a fine HA pair…','--green'),cap:'You can have the finest <b>HA firewall pair</b> – two devices, quiet takeover, state synchronization.'},
  {glow:c14g('lb','--red')+c14g('s1','--red'),dyn:c14pkt('M 380 108 L 530 56','--red')+c14lbl(455,211,'…but a single server behind it = SPOF ⚠','--red'),cap:'…but if a <b>single server</b> hangs behind it, the service drops anyway. No single redundancy is enough alone.'},
  {glow:c14g('cli','--cyan')+c14g('fwa','--cyan')+c14g('lb','--cyan')+c14g('s1','--cyan'),dyn:c14pkt('M 70 108 L 220 56 L 380 108 L 530 56','--cyan')+c14lbl(150,211,'every link of the chain needs a backup','--cyan'),cap:'Resilience is designed <b>in layers</b>: at every hop ask ‘what if this piece dies?’. The chain is only as strong as its weakest link.'},
  {glow:c14g('cli','--blue')+c14g('fwb','--blue')+c14g('lb','--blue')+c14g('s2','--blue'),dyn:c14pkt('M 70 108 L 220 160 L 380 108 L 530 160','--blue')+c14lbl(150,211,'loop: build → test N-1 → strengthen → repeat','--blue'),cap:'Design is a <b>loop</b>: build a layer, test N-1, find the weakest link, strengthen it, test again.'}
]);}
/* ---------- L5M2 — Cost vs benefit ---------- */
function renderC14Cost(){return c14P('ran',
  'If resilience is so great, why not double absolutely everything, always? Because redundancy <b>costs something</b> – and blind ‘two of everything’ is the same mistake as no redundancy, just pricier. Each doubled device means <b>double the purchase</b>, more space, more power, and above all <b>more complexity</b>: more configuration, more things that can break or be set up wrong. And beware – <b>complexity itself is a risk</b>: a misconfigured HA pair can take down a network in ways a single device never could (recall split-brain). So how to decide where you want redundancy and where it is overkill? With the same tool as in the OT course: <b>risk analysis</b>. Ask two questions. <b>How often does it fail</b> (probability) and <b>what happens when it does</b> (impact)? High impact → redundancy almost always pays off: a company e-shop that loses hundreds of thousands per hour of outage wants an HA pair, a load balancer and multi-WAN. Low impact → a plain backup or nothing suffices: a home network survives the router dropping for five minutes once a year – buying a second one is overkill. And a key idea often forgotten: before reaching for expensive real-time redundancy, weigh cheaper <b>backups and fast recovery</b>. For many services a few minutes of outage and a quick restore from backup is acceptable – at a fraction of the cost of full HA. Resilience is not a contest of ‘who has more nines’, but a <b>considered choice of how much of that cost you are willing to pay for how much certainty</b>.',
  [['cost vs benefit','every doubling costs money, space and above all complexity; blind ‘two of everything’ is a pricier mistake.'],['risk analysis','probability × impact decides: high impact → redundancy; low → a backup or nothing.'],['complexity is a risk','a misconfigured HA pair can crash a network worse than a single device (split-brain).']]);}
function mountC14Cost(){c14Mount('ran',[
  {glow:c14g('fwa','--amber')+c14g('fwb','--amber')+c14g('s1','--amber')+c14g('s2','--amber'),dyn:c14lbl(220,20,'2× firewall','--amber')+c14lbl(530,20,'2× server','--amber')+c14lbl(380,20,'+ 2× licenses, space, power','--amber')+c14lbl(220,211,'two of everything = double cost and complexity','--amber'),cap:'Redundancy costs: double purchase, more space and power, and above all <b>more complexity</b>. Blind ‘two of everything’ is a pricier mistake.'},
  {glow:c14g('cli','--red')+c14g('fwa','--red')+c14g('fwb','--red'),dyn:c14pkt('M 84 103 L 206 61','--red')+c14pkt('M 84 113 L 206 155','--red')+c14lbl(310,40,'FW-A: I am active','--red')+c14lbl(310,180,'FW-B: I am active too ⚠','--red')+c14lbl(220,211,'complexity itself is a risk (split-brain) ⚠','--red'),cap:'And beware: <b>complexity is a risk</b>. A misconfigured HA pair can crash a network worse than a single device.'},
  {glow:c14g('cli','--blue')+c14g('fwa','--blue')+c14g('lb','--blue')+c14g('s1','--blue'),dyn:c14pkt('M 70 108 L 220 56 L 380 108 L 530 56','--blue')+c14lbl(150,211,'high impact → redundancy pays off','--blue'),cap:'<b>Risk analysis</b> decides (probability × impact). An e-shop losing hundreds of thousands per hour of outage wants HA and multi-WAN.'},
  {glow:c14g('s1','--green'),dyn:c14lbl(530,20,'1 server + a backup, restore in 15 min','--green')+c14lbl(530,108,'low impact → a backup and fast recovery suffice','--green'),cap:'Low impact → overkill. Before expensive HA, weigh cheap <b>backups and fast recovery</b> – a few minutes of outage is often fine.'}
]);}
/* ---------- L5M3 — Summary ---------- */
function renderC14Summary(){return c14P('rao',
  'The course ends – let us assemble resilience and scaling into one picture. <b>Find the weak spot</b>: a SPOF is a device whose failure takes down the whole network; the goal is <b>N-1</b> (withstand any single piece failing), and the tools are the topology check and the resilience test (lesson 1). <b>Ensure availability</b>: an <b>HA pair</b> doubles a firewall or router – active/standby or active/active, with quiet failover and state synchronization so takeover does not drop connections; beware split-brain (lesson 2). <b>Scale out</b>: a <b>load balancer</b> hides a server pool behind one VIP, splits the load (round-robin, least-conn, weighted, sticky) and removes a dead backend by itself via the health check – scale-out and resilience in one (lesson 3). <b>Use the right tool on the right layer</b>: STP and LAG on L2, HSRP/VRRP on the gateway, an HA pair on the firewall, a load balancer on the servers, multi-WAN on the internet – and do not forget the power (lesson 4). <b>Design with restraint</b>: no single redundancy suffices, a chain is only as strong as its weakest link, and how much of the cost you pay is decided by risk analysis (lesson 5). Notice the common thread: almost none of this was new magic – the virtual IP, floating static, STP, the stateful firewall you know from earlier courses. Resilience is largely a <b>way of thinking</b>: at every device ask ‘and what if this dies?’ – and have the answer ready before it happens.',
  [['resilience = a way of thinking','at every device ask ‘what if this dies?’ and have the answer before it happens.'],['the course thread','find the SPOF → ensure availability (HA) → scale (LB) → the right tool per layer → design with restraint.']]);}
function mountC14Summary(){c14Mount('rao',[
  {glow:c14g('cli','--amber')+c14g('fwa','--amber')+c14g('lb','--amber')+c14g('s1','--amber'),dyn:c14pkt('M 70 108 L 220 56 L 380 108 L 530 56','--amber')+c14lbl(150,211,'find the SPOF, aim for N-1 (lesson 1)','--amber'),cap:'<b>Find the weak spot</b>: a SPOF takes down the whole network; the goal is N-1. Tools: the topology check and the resilience test.'},
  {glow:c14g('cli','--green')+c14g('fwb','--green')+c14g('lb','--green'),dyn:c14pkt('M 70 108 L 220 160 L 380 108','--green')+c14lbl(150,211,'HA pair: quiet takeover (lesson 2)','--green'),cap:'<b>Ensure availability</b>: an HA pair doubles a firewall/router with failover and state sync – beware split-brain.'},
  {glow:c14g('lb','--blue')+c14g('s1','--blue')+c14g('s2','--blue'),dyn:c14pkt('M 380 108 L 530 160','--blue')+c14lbl(455,211,'load balancer: VIP + pool (lesson 3)','--blue'),cap:'<b>Scale out</b>: the load balancer hides a pool behind a VIP, splits load and removes a dead backend via the health check.'},
  {glow:c14g('cli','--cyan')+c14g('fwa','--cyan')+c14g('fwb','--cyan')+c14g('lb','--cyan')+c14g('s1','--cyan')+c14g('s2','--cyan'),dyn:c14lbl(150,211,'right tool per layer + restraint (lessons 4–5)','--cyan'),cap:'<b>The right tool per layer</b> (STP, HSRP, HA, LB, multi-WAN) and <b>design with restraint</b> by risk analysis. Congratulations – now try it in the simulator!'}
]);}

